import pytest
from playwright.sync_api import Page, expect

TARGET_URL = 'https://the-internet.herokuapp.com/login'
SUCCESS_FLASH = 'You logged into a secure area!'


@pytest.mark.smoke
@pytest.mark.parametrize(
    "username,password,expected_url,expected_error",
    [('tomsmith', 'SuperSecretPassword!', 'https://the-internet.herokuapp.com/secure', None), ('tomsmith', 'wrong_password', None, 'Your password is invalid!'), ('wrong_user', 'SuperSecretPassword!', None, 'Your username is invalid!'), ('', 'SuperSecretPassword!', None, 'Your username is invalid!')],
    ids=['login_success', 'login_wrong_password', 'login_wrong_username', 'login_empty_username'],
)
def test_login_cases(page: Page, username, password, expected_url, expected_error):
    page.goto(TARGET_URL)
    page.locator('#username').fill(username)
    page.locator('#password').fill(password)
    page.locator('button[type=submit]').click()
    if expected_error is not None:
        expect(page.locator('#flash')).to_contain_text(expected_error)
        expect(page).to_have_url(TARGET_URL)
        return
    expect(page).to_have_url(expected_url)
    expect(page.locator('#flash')).to_contain_text(SUCCESS_FLASH)
